using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Downloads a file from the cloud. Download progress and completion of the download will be notified through updateFile updates
    /// </summary>
    public Task<TdLib.TdApi.Objects.File> DownloadFileAsync(int fileId = default, int priority = default, long offset = default, long limit = default, bool synchronous = default)
    {

           using var activity =  StartCallActivity("DownloadFileAsync", typeof(DownloadFile).FullName ?? "DownloadFileAsync");

           try
           {
             return client.DownloadFileAsync(fileId, priority, offset, limit, synchronous);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
